INSERT INTO track (id, album_id, disc_number, name, lyrics, external_urls) VALUES ('27tNWlJeNuIJbY0OM63Z2W', '4eLPsYPBmKkvIiYbbCY2Nq', 1, 'Headlines', 'I might be too strung out on compliments, overdosed on confidence
